parameters.functionCode:
// Toma la respuesta de Claude (texto JSON) y arma el archivo .md con frontmatter
const claudeText = items[0].json.content[0].text;
const parsed = JSON.parse(claudeText);
const slug = parsed.title.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const frontmatter = `---
title: "${parsed.title.replace(/"/g, '\\"')}"
dek: "${parsed.dek.replace(/"/g, '\\"')}"
category: "${parsed.category}"
source_name: "${$node['Procesar noticia por noticia'].json.sourceName || 'Fuente'}"
source_url: "${$node['Procesar noticia por noticia'].json.link}"
published_at: "${new Date().toISOString()}"
breaking: ${parsed.breaking}
generated_by: "pipeline"
---

${parsed.body_markdown}
`;
return [{ json: { slug, filename: `src/content/articles/${slug}.md`, content: frontmatter, title: parsed.title, dek: parsed.dek } }];
